// Test-only data: a made-up espresso thread with findings, a cluster and
// histories, generated by `npm run demo` in inference/. Never shown on the site.
import type { AnalysisResource, EnrichmentJob, GraphEnvelope, InvestigationResource } from '../api/contract';
import { buildReport } from '../analysis/report';
import data from './synthetic-espresso-report.json';

export const testDemo = data as unknown as {
  investigation: InvestigationResource;
  graph: GraphEnvelope;
  enrichments: EnrichmentJob[];
  analysis: AnalysisResource;
};
export const testReport = buildReport(testDemo.analysis, testDemo.graph, testDemo.enrichments);
